590	export function QuoteScreen({ onCancel, onExit }: { onCancel: () => void; onExit: () => void }) {
591	  const queryClient = useQueryClient();
592	  const [clientId, setClientId]             = useState('');
593	  const [lines, setLines]                   = useState<QuoteDraftLine[]>([{ id: 1, description: '', qty: '1', unitPrice: '' }]);
594	  const [depositEnabled, setDepositEnabled] = useState(false);
595	  const [depositType, setDepositType]       = useState<'percent' | 'fixed'>('percent');
596	  const [depositValue, setDepositValue]     = useState('20');
597	  const [notes, setNotes]                   = useState('');
598	  const [created, setCreated]               = useState<any>(null);
599	  const [error, setError]                   = useState('');
600	
601	  const { data: clients = [] } = useQuery<any[]>({
602	    queryKey: ['/api/trades/clients'],
603	    queryFn: () => tradesFetch('/api/trades/clients').then(r => r.ok ? r.json() : []),
604	  });
605	  const { data: auth } = useQuery<any>({
606	    queryKey: ['/api/auth/me', 'trades-quote'],
607	    queryFn: () => tradesFetch('/api/auth/me').then(r => r.ok ? r.json() : null),
608	  });
609	
610	  const gstMode = auth?.user?.tradeGstMode === 'exclusive' ? 'exclusive' : 'inclusive';
611	  const totals = useMemo(() => {
612	    const lineInputs = lines.map(line => ({
613	      qty: Math.max(0, Number(line.qty) || 0),
614	      unitPriceCents: Math.max(0, Math.round((Number(line.unitPrice) || 0) * 100)),
615	    }));
616	    const depositInput = depositEnabled
617	      ? depositType === 'percent' ? Number(depositValue) || 0 : Math.round((Number(depositValue) || 0) * 100)
618	      : undefined;
619	    const computed = computeQuoteTotals(lineInputs, {
620	      gstRegistered: !!auth?.user?.gstRegistered,
621	      gstMode,
622	      depositEnabled,
623	      depositType: depositEnabled ? depositType : undefined,
