51	/* ── Add Tenant Sheet ── */
52	function AddTenantSheet({ onClose, onSave, saving, saveError }: {
53	  onClose: () => void;
54	  onSave: (data: any) => void;
55	  saving: boolean;
56	  saveError: string | null;
57	}) {
58	  const [form, setForm] = useState({
59	    firstName: '', lastName: '', email: '', phone: '',
60	    propertyAddress: '', preferredChannel: 'email' as 'email' | 'whatsapp' | 'sms',
