91	          const detail = [s.email, s.phone].filter(Boolean).join(', ');
92	          return detail ? `${s.name} (${detail})` : s.name;
93	        }).join('\n')
94	      : '';
95	    onSave({ ...form, coTenantsText });
96	  };
97	
98	  const ANIM_IN  = 'atSlideUp 0.38s cubic-bezier(0.16,1,0.3,1) both';
99	  const ANIM_OUT = 'atSlideDown 0.32s cubic-bezier(0.4,0,0.2,1) both';
100	  const FD_IN    = 'atFdIn 0.28s ease both';
101	  const FD_OUT   = 'atFdOut 0.28s ease both';
102	
103	  return (
104	    <div style={{ position: 'fixed', inset: 0, zIndex: 100 }}>
105	      <style>{`
106	        @keyframes atSlideUp   { from { transform: translateY(100%); } to { transform: translateY(0); } }
107	        @keyframes atSlideDown { from { transform: translateY(0); } to { transform: translateY(100%); } }
108	        @keyframes atFdIn      { from { opacity: 0; } to { opacity: 1; } }
109	        @keyframes atFdOut     { from { opacity: 1; } to { opacity: 0; } }
110	      `}</style>
111	
112	      {/* Backdrop */}
113	      <div
114	        onClick={handleClose}
115	        style={{
116	          position: 'absolute', inset: 0,
117	          background: 'rgba(4,13,109,0.55)',
118	          backdropFilter: 'blur(8px)',
119	          WebkitBackdropFilter: 'blur(8px)',
120	          animation: closing ? FD_OUT : FD_IN,
121	        }}
122	      />
123	
124	      {/* Centering wrapper — keeps sheet at 390px on desktop */}
125	      <div style={{ position: 'absolute', bottom: 0, left: 0, right: 0, display: 'flex', justifyContent: 'center' }}>
126	      {/* Sheet — slides up from bottom */}
127	      <div style={{
128	        width: '100%', maxWidth: 390,
129	        background: '#F4F4F4',
130	        borderRadius: '28px 28px 0 0',
131	        maxHeight: '92vh',
132	        overflowY: 'auto',
133	        animation: closing ? ANIM_OUT : ANIM_IN,
134	      }}>
135	        {/* Pull handle */}
136	        <div style={{ display: 'flex', justifyContent: 'center', padding: '14px 0 2px' }}>
137	          <div style={{ width: 36, height: 4, borderRadius: 2, background: 'rgba(0,0,0,0.1)' }} />
138	        </div>
139	
140	        <div style={{ padding: '12px 24px 52px' }}>
141	          {/* Header */}
142	          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24 }}>
143	            <span style={{ fontWeight: 700, fontSize: 20, color: C.navy, letterSpacing: '-0.3px' }}>add tenant</span>
144	            <button onClick={handleClose} style={{ width: 32, height: 32, borderRadius: 999, background: C.gray, border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
145	              <svg width={14} height={14} viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="2.4" strokeLinecap="round"><path d="M5 5l14 14M19 5L5 19"/></svg>
146	            </button>
147	          </div>
148	
149	          {/* Main tenant fields */}
150	          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 12px' }}>
151	            <Field label="first name" value={form.firstName} onChange={set('firstName')} required />
152	            <Field label="last name"  value={form.lastName}  onChange={set('lastName')}  required />
153	          </div>
154	          <Field label="property address" value={form.propertyAddress} onChange={set('propertyAddress')} required />
155	          <Field label="email" value={form.email} onChange={set('email')} type="email" />
156	          <Field label="phone" value={form.phone} onChange={set('phone')} type="tel" />
157	
158	          {/* Preferred channel */}
159	          <div style={{ marginBottom: 24 }}>
160	            <div style={{ fontSize: 11, fontWeight: 600, color: C.sky, letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 8 }}>send rent link via</div>
161	            <div style={{ display: 'flex', gap: 8 }}>
162	              {(['email', 'whatsapp', 'sms'] as const).map(ch => (
163	                <button key={ch} onClick={() => setForm(f => ({ ...f, preferredChannel: ch }))}
164	                  style={{ flex: 1, padding: '13px 0', borderRadius: 14, border: 'none', background: form.preferredChannel === ch ? C.navy : C.gray, color: form.preferredChannel === ch ? C.white : C.navy, fontWeight: 600, fontSize: 12.5, cursor: 'pointer', textTransform: 'uppercase', letterSpacing: '0.04em', transition: 'background 0.18s, color 0.18s' }}>
165	                  {ch}
166	                </button>
167	              ))}
168	            </div>
169	            {!channelContactOk && (
170	              <div style={{ marginTop: 8, fontSize: 12, color: '#C71A2A', fontWeight: 500 }}>
171	                add {form.preferredChannel === 'email' ? 'an email address' : 'a phone number'} above to send via {form.preferredChannel}
172	              </div>
173	            )}
174	          </div>
175	
176	          {/* ── Subtenants ── */}
177	          <div style={{ marginBottom: 24 }}>
178	            <div style={{ fontSize: 11, fontWeight: 600, color: C.sky, letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 10 }}>subtenants</div>
179	
180	            {/* Added subtenants list */}
181	            {subtenants.map((s, i) => (
182	              <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '11px 14px', marginBottom: 8, borderRadius: 14, background: C.gray }}>
183	                <div style={{ width: 30, height: 30, borderRadius: 999, background: C.navy, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, fontSize: 11, fontWeight: 700, color: C.sky }}>
184	                  {s.name.split(' ').map((w: string) => w[0]).join('').slice(0, 2).toUpperCase()}
185	                </div>
186	                <div style={{ flex: 1, minWidth: 0 }}>
187	                  <div style={{ fontWeight: 600, fontSize: 14, color: C.navy }}>{s.name}</div>
188	                  {(s.email || s.phone) && (
189	                    <div style={{ fontWeight: 400, fontSize: 12, color: C.mute, marginTop: 1 }}>
190	                      {[s.email, s.phone].filter(Boolean).join(' · ')}
191	                    </div>
192	                  )}
193	                </div>
194	                <button onClick={() => setSubtenants(p => p.filter((_, j) => j !== i))}
195	                  style={{ width: 26, height: 26, borderRadius: 999, background: 'rgba(4,13,109,0.08)', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
196	                  <svg width={12} height={12} viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="2.4" strokeLinecap="round"><path d="M5 5l14 14M19 5L5 19"/></svg>
197	                </button>
198	              </div>
199	            ))}
200	
201	            {/* Add subtenant toggle button */}
202	            <button
203	              onClick={() => setSubOpen(o => !o)}
204	              style={{ width: '100%', padding: '13px 0', borderRadius: 14, border: `1.5px dashed ${subOpen ? C.sky : 'rgba(4,13,109,0.18)'}`, background: subOpen ? 'rgba(88,171,255,0.06)' : 'transparent', color: C.navy, fontWeight: 600, fontSize: 14, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, transition: 'all 0.22s ease' }}>
205	              <svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.sky} strokeWidth="2.4" strokeLinecap="round"><path d="M12 5v14M5 12h14"/></svg>
206	              <span style={{ color: C.navy }}>add subtenant</span>
207	            </button>
208	
209	            {/* Expandable subtenant form — smooth slide */}
210	            <div style={{
211	              overflow: 'hidden',
212	              maxHeight: subOpen ? '320px' : '0px',
213	              transition: 'max-height 0.38s cubic-bezier(0.16,1,0.3,1)',
214	            }}>
215	              <div style={{ paddingTop: 14, display: 'flex', flexDirection: 'column', gap: 10 }}>
216	                <Field label="name" value={subForm.name} onChange={setSub('name')} required />
217	                <Field label="email" value={subForm.email} onChange={setSub('email')} type="email" />
218	                <Field label="phone" value={subForm.phone} onChange={setSub('phone')} type="tel" />
219	                <button
220	                  onClick={confirmSubtenant}
221	                  disabled={!subForm.name.trim()}
222	                  style={{ padding: '13px 0', borderRadius: 14, background: subForm.name.trim() ? C.navy : C.gray, color: subForm.name.trim() ? C.white : C.mute, fontWeight: 600, fontSize: 14, border: 'none', cursor: subForm.name.trim() ? 'pointer' : 'default', transition: 'background 0.18s' }}>
223	                  confirm subtenant
224	                </button>
225	              </div>
226	            </div>
227	          </div>
228	
229	          {/* Error */}
230	          {saveError && (
231	            <div style={{ marginBottom: 16, padding: '12px 16px', borderRadius: 14, background: 'rgba(255,59,78,0.07)', border: '1px solid rgba(255,59,78,0.18)' }}>
232	              <p style={{ color: '#C71A2A', fontSize: 13, fontWeight: 500, margin: 0 }}>{saveError}</p>
233	            </div>
234	          )}
235	
236	          {/* Save */}
237	          <button
238	            onClick={handleSave}
239	            disabled={!valid || saving}
240	            style={{ width: '100%', padding: '18px 0', borderRadius: 999, background: valid && !saving ? C.navy : C.gray, color: valid && !saving ? C.white : C.mute, fontWeight: 700, fontSize: 16, border: 'none', cursor: valid && !saving ? 'pointer' : 'default', transition: 'background 0.2s, color 0.2s' }}>
241	            {saving ? 'adding…' : 'add tenant'}
242	          </button>
243	        </div>
244	      </div>
245	      </div>
246	    </div>
247	  );
248	}
