250	/* ── Tenant list row ── */
251	function initials(tenant: any) {
252	  return `${tenant.firstName?.[0] ?? ''}${tenant.lastName?.[0] ?? ''}`.toUpperCase() || '?';
253	}
254	
255	function fmtDue(nextInvoice: any) {
256	  if (!nextInvoice?.dueAt) return '';
257	  return new Date(nextInvoice.dueAt).toLocaleDateString('en-NZ', { day: '2-digit', month: '2-digit' });
258	}
259	
260	function TenantRow({ tenant, nextInvoice, onClick }: { tenant: any; nextInvoice: any; onClick: () => void }) {
261	  const fullName = `${tenant.firstName} ${tenant.lastName}`.trim();
262	  const overdue = nextInvoice?.status === 'overdue';
263	
264	  return (
265	    <button type="button" className="tdir-row" onClick={onClick}>
266	      <span className="tdir-avatar">{initials(tenant)}</span>
267	      <span className="tdir-copy">
268	        <span className="tdir-name">{fullName}</span>
269	        <span className="tdir-address">{tenant.propertyAddress}</span>
270	      </span>
271	      <span className="tdir-money">
272	        <span>{nextInvoice ? fmtCents(nextInvoice.amountCents) : '—'}</span>
273	        {nextInvoice ? (
274	          <small className={overdue ? 'overdue' : ''}>{overdue ? 'overdue' : 'next payment'}<br />{fmtDue(nextInvoice)}</small>
275	        ) : (
276	          <small>no invoice</small>
277	        )}
278	      </span>
279	    </button>
280	  );
281	}
