283	export default function TenantDirectory() {
284	  const [, setLocation] = useLocation();
285	  const [search,    setSearch]    = useState('');
286	  const [showAdd,   setShowAdd]   = useState(false);
287	  const [showArchived, setShowArchived] = useState(false);
288	  const [saveError, setSaveError] = useState<string | null>(null);
289	  const queryClient = useQueryClient();
290	  const heroRef = useRef<HTMLDivElement>(null);
291	
292	  // Signal the hero is mounted so a reverse hero-morph (profile → directory)
293	  // can capture and play (see property-transition.ts).
294	  useLayoutEffect(() => { signalPropertyReady(); }, []);
295	
296	  const { data: tenants = [], isLoading } = usePropertyTenants();
297	  const { data: invoices = [] } = usePropertyInvoices();
298	
299	  // Archived tenants — fetched lazily only when the merchant expands the section.
300	  const { data: archivedTenants = [] } = useQuery<any[]>({
301	    queryKey: ['/api/property/tenants', 'archived'],
302	    queryFn: () => propFetch('/api/property/tenants?includeArchived=true').then(r => r.ok ? r.json() : []),
303	    select: (list: any[]) => list.filter((t: any) => t.status === 'archived'),
304	    enabled: showArchived,
305	    staleTime: 30000,
306	    retry: false,
307	  });
308	
309	  const restoreMutation = useMutation({
310	    mutationFn: async (id: string) => {
311	      const r = await fetch(`/api/property/tenants/${id}/unarchive`, { method: 'POST', headers: propHeaders() });
312	      if (!r.ok) throw new Error('Failed to restore');
313	      return r.json();
314	    },
315	    onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['/api/property/tenants'] }); },
316	  });
317	
318	  const createMutation = useMutation({
319	    mutationFn: async (data: any) => {
320	      const r = await fetch('/api/property/tenants', {
321	        method: 'POST',
322	        headers: { 'Content-Type': 'application/json', ...propHeaders() },
323	        body: JSON.stringify(data),
324	      });
325	      if (!r.ok) {
326	        const msg = await r.json().then(d => d.message).catch(() => `Error ${r.status}`);
327	        throw new Error(msg);
328	      }
329	      return r.json();
330	    },
331	    onSuccess: () => {
332	      queryClient.invalidateQueries({ queryKey: ['/api/property/tenants'] });
333	      setSaveError(null);
334	      setShowAdd(false);
335	    },
336	    onError: (err: any) => {
337	      setSaveError(err?.message || 'Failed to add tenant. The backend may not be connected yet.');
338	    },
339	  });
340	
341	  /* Helpers */
342	  const activeTenants = tenants.filter((t: any) => t.status !== 'archived');
343	  const term = search.trim().toLowerCase();
344	  const filtered = activeTenants.filter((t: any) =>
345	    !term || `${t.firstName} ${t.lastName}`.toLowerCase().includes(term) || t.propertyAddress.toLowerCase().includes(term)
346	  );
347	  const tenantCountLabel = `active tenant${activeTenants.length !== 1 ? 's' : ''}`;
348	
349	  // Return the invoice that represents the worst-case status for this tenant
350	  // (overdue > dispatched/pending > paid). Fallback to most recent for display.
351	  const invoiceByTenant = (tenantId: string) => {
352	    const live = invoices.filter((i: any) => i.tenantProfileId === tenantId && i.status !== 'voided');
353	    if (live.length === 0) return undefined;
354	    const overdue = live.find((i: any) => i.status === 'overdue');
355	    if (overdue) return overdue;
356	    const pending = live.find((i: any) => ['dispatched', 'pending_dispatch', 'dispatch_failed'].includes(i.status));
357	    if (pending) return pending;
358	    return [...live].sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())[0];
359	  };
360	
361	  return (
362	    <div style={{ background: C.white, minHeight: '100svh', display: 'flex', justifyContent: 'center' }}>
363	    <div style={{ width: '100%', maxWidth: 430, minHeight: '100svh', background: C.sheet, paddingBottom: 128, fontFamily: "'Outfit', system-ui, sans-serif", overflow: 'hidden' }}>
364	      <style>{DIRECTORY_CSS}</style>
365	
366	      {/* Hero — carries view-transition-name so it morphs into the profile hero */}
367	      <section ref={heroRef} className="pt-hero tdir-hero">
368	        {/* Contents bounce, not the section — its view-transition morph needs a stable box */}
369	        <div className="pt-bounce tdir-hero-count" style={{ '--pt-d': '0ms' } as any}>{activeTenants.length}</div>
370	        <div className="pt-bounce tdir-hero-label" style={{ '--pt-d': '60ms' } as any}>{tenantCountLabel}</div>
371	      </section>
372	
373	      <main className="tdir-body">
374	        <button type="button" className="tdir-add" onPointerDown={pulse} onClick={() => setShowAdd(true)} aria-label="Add tenant">
375	          <svg width={26} height={26} viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="2.6" strokeLinecap="round"><path d="M12 5v14M5 12h14" /></svg>
376	        </button>
377	        <div className="pt-bounce tdir-search-row" style={{ '--pt-d': '140ms' } as any}>
378	          <label className="tdir-search">
379	            <input
380	              value={search}
381	              onChange={e => setSearch(e.target.value)}
382	              placeholder="search tenants or address"
383	            />
384	            {search && (
385	              <button type="button" onClick={() => setSearch('')} aria-label="Clear search">
386	                <svg width={15} height={15} viewBox="0 0 24 24" fill="none" stroke={C.mute} strokeWidth="2.2" strokeLinecap="round"><path d="M6 6l12 12M18 6 6 18" /></svg>
387	              </button>
388	            )}
389	          </label>
390	          <button
391	            type="button"
392	            onClick={() => startPropertyBack(() => setLocation('/property'), { expectHero: false })}
393	            aria-label="Go to property dashboard"
394	            className="tdir-grid-btn"
395	          >
396	            <svg width={17} height={17} viewBox="0 0 20 20" fill={C.sky}><rect x="1" y="1" width="7" height="7" rx="1.5" /><rect x="12" y="1" width="7" height="7" rx="1.5" /><rect x="1" y="12" width="7" height="7" rx="1.5" /><rect x="12" y="12" width="7" height="7" rx="1.5" /></svg>
397	          </button>
398	        </div>
399	
400	        <div className="tdir-list">
401	          {isLoading ? (
402	            <div className="pt-bounce tdir-empty" style={{ '--pt-d': '190ms' } as any}>loading tenants...</div>
403	          ) : filtered.length === 0 ? (
404	            <div className="pt-bounce tdir-empty" style={{ '--pt-d': '190ms' } as any}>
405	              {search ? `no tenants match "${search}"` : 'no tenants yet - tap + to add your first'}
406	            </div>
407	          ) : (
408	            filtered.map((t: any, i: number) => (
409	              <div key={t.id} className="pt-bounce" style={{ '--pt-d': `${190 + Math.min(i, 12) * 45}ms` } as any}>
410	              <TenantRow
411	                tenant={t}
412	                nextInvoice={invoiceByTenant(t.id)}
413	                onClick={() => {
414	                  const inv = invoiceByTenant(t.id);
415	                  startPropertyNavigation(
416	                    {
417	                      id: t.id,
418	                      firstName: t.firstName,
419	                      lastName: t.lastName,
420	                      propertyAddress: t.propertyAddress,
421	                      preferredChannel: t.preferredChannel,
422	                      invoiceStatus: inv?.status,
423	                    },
424	                    () => setLocation(`/property/tenants/${t.id}`)
425	                  );
426	                }}
427	              />
428	              </div>
429	            ))
430	          )}
431	        </div>
432	
433	        <div className="pt-bounce tdir-archived" style={{ '--pt-d': `${190 + (Math.min(filtered.length, 12) + 1) * 45}ms` } as any}>
434	          <button type="button" onClick={() => setShowArchived(s => !s)}>
435	            {showArchived ? 'hide archived' : 'show archived'}
436	          </button>
437	          {showArchived && (
438	            archivedTenants.length === 0 ? (
439	              <div className="tdir-archived-empty">no archived tenants</div>
440	            ) : (
441	              <div className="tdir-archived-list">
442	                {archivedTenants.map((t: any) => (
443	                  <div key={t.id} className="tdir-archive-row">
444	                    <div>
445	                      <strong>{t.firstName} {t.lastName}</strong>
446	                      <span>{t.propertyAddress}</span>
447	                    </div>
448	                    <button type="button" onClick={() => restoreMutation.mutate(t.id)} disabled={restoreMutation.isPending}>restore</button>
449	                  </div>
450	                ))}
451	              </div>
452	            )
453	          )}
454	        </div>
455	      </main>
456	
457	      {/* Add tenant sheet */}
458	      {showAdd && (
459	        <AddTenantSheet
460	          onClose={() => { setShowAdd(false); setSaveError(null); }}
461	          onSave={data => { setSaveError(null); createMutation.mutate(data); }}
462	          saving={createMutation.isPending}
463	          saveError={saveError}
464	        />
465	      )}
466	    </div>
467	    </div>
