131	
132	  const channelContactOk = form.preferredChannel === "email" ? !!form.email.trim() : !!form.phone.trim();
133	  const valid = !!form.firstName.trim() && !!form.lastName.trim() && !!form.siteAddress.trim() && channelContactOk;
134	
135	  const handleClose = () => {
136	    setClosing(true);
137	    setTimeout(onClose, 320);
138	  };
139	
140	  const handleSave = () => {
141	    if (!valid || saving) return;
142	    onSave(form);
143	  };
144	
145	  const animIn = "atSlideUp 0.38s cubic-bezier(0.16,1,0.3,1) both";
146	  const animOut = "atSlideDown 0.32s cubic-bezier(0.4,0,0.2,1) both";
147	  const fadeIn = "atFdIn 0.28s ease both";
148	  const fadeOut = "atFdOut 0.28s ease both";
149	
150	  return (
151	    <div style={{ position: "fixed", inset: 0, zIndex: 100 }}>
152	      <style>{`
153	        @keyframes atSlideUp { from { transform: translateY(100%); } to { transform: translateY(0); } }
154	        @keyframes atSlideDown { from { transform: translateY(0); } to { transform: translateY(100%); } }
155	        @keyframes atFdIn { from { opacity: 0; } to { opacity: 1; } }
156	        @keyframes atFdOut { from { opacity: 1; } to { opacity: 0; } }
157	      `}</style>
158	
159	      <div
160	        onClick={handleClose}
161	        style={{
162	          position: "absolute",
163	          inset: 0,
164	          background: "rgba(4,13,109,0.55)",
165	          backdropFilter: "blur(8px)",
166	          WebkitBackdropFilter: "blur(8px)",
167	          animation: closing ? fadeOut : fadeIn,
168	        }}
169	      />
170	
171	      <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, display: "flex", justifyContent: "center" }}>
172	        <div style={{ width: "100%", maxWidth: 390, background: C.cream, borderRadius: "28px 28px 0 0", maxHeight: "92vh", overflowY: "auto", animation: closing ? animOut : animIn }}>
173	          <div style={{ display: "flex", justifyContent: "center", padding: "14px 0 2px" }}>
174	            <div style={{ width: 36, height: 4, borderRadius: 2, background: "rgba(0,0,0,0.1)" }} />
175	          </div>
176	
177	          <div style={{ padding: "12px 24px 52px" }}>
178	            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 24 }}>
179	              <span style={{ fontWeight: 700, fontSize: 20, color: C.ink, letterSpacing: 0 }}>add client</span>
180	              <button
181	                onClick={handleClose}
182	                aria-label="Close add client sheet"
183	                style={{ width: 32, height: 32, borderRadius: 999, background: C.gray, border: "none", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}
184	              >
185	                <X size={15} color={C.ink} strokeWidth={2.4} />
186	              </button>
187	            </div>
188	
189	            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 12px" }}>
190	              <Field label="first name" value={form.firstName} onChange={setText("firstName")} required />
191	              <Field label="last name" value={form.lastName} onChange={setText("lastName")} required />
192	            </div>
193	            <Field label="site address" value={form.siteAddress} onChange={setText("siteAddress")} required />
194	            <Field label="email" value={form.email} onChange={setText("email")} type="email" />
195	            <Field label="phone" value={form.phone} onChange={setText("phone")} type="tel" />
196	
197	            <div style={{ marginBottom: 24 }}>
198	              <div style={{ fontSize: 11, fontWeight: 700, color: C.panel, letterSpacing: 0, textTransform: "uppercase", marginBottom: 8 }}>send invoice via</div>
199	              <div style={{ display: "flex", gap: 8 }}>
200	                {(["email", "whatsapp", "sms"] as const).map((channel) => (
201	                  <button
202	                    key={channel}
203	                    onClick={() => setForm((current) => ({ ...current, preferredChannel: channel }))}
204	                    style={{ flex: 1, padding: "13px 0", borderRadius: 14, border: "none", background: form.preferredChannel === channel ? C.ink : C.gray, color: form.preferredChannel === channel ? C.cream : C.ink, fontWeight: 700, fontSize: 12.5, cursor: "pointer", textTransform: "uppercase", letterSpacing: 0, transition: "background 0.18s, color 0.18s" }}
205	                  >
206	                    {channel}
207	                  </button>
208	                ))}
209	              </div>
210	              {!channelContactOk && (
211	                <div style={{ marginTop: 8, fontSize: 12, color: "#C71A2A", fontWeight: 600 }}>
212	                  add {form.preferredChannel === "email" ? "an email address" : "a phone number"} above to send via {form.preferredChannel}
213	                </div>
214	              )}
215	            </div>
216	
217	            <TextAreaField label="notes" value={form.notes} onChange={setText("notes")} placeholder="job access, parking, gate code" />
218	
219	            {saveError && (
220	              <div style={{ marginBottom: 16, padding: "12px 16px", borderRadius: 14, background: "rgba(255,59,78,0.07)", border: "1px solid rgba(255,59,78,0.18)" }}>
221	                <p style={{ color: "#C71A2A", fontSize: 13, fontWeight: 600, margin: 0 }}>{saveError}</p>
222	              </div>
223	            )}
224	
225	            <button
226	              onClick={handleSave}
227	              disabled={!valid || saving}
228	              style={{ width: "100%", padding: "18px 0", borderRadius: 999, background: valid && !saving ? C.ink : C.gray, color: valid && !saving ? C.cream : C.mute, fontWeight: 700, fontSize: 16, border: "none", cursor: valid && !saving ? "pointer" : "default", transition: "background 0.2s, color 0.2s" }}
229	            >
230	              {saving ? "adding..." : "add client"}
231	            </button>
232	          </div>
233	        </div>
234	      </div>
235	    </div>
236	  );
237	}
238	
239	function invoiceStatus(invoice: any): string {
240	  if (!invoice) return "upcoming";
241	  if (invoice.status === "paid" || invoice.status === "paid_external") return "paid";
242	  if (invoice.status === "overdue") return "overdue";
243	  if (invoice.status === "dispatch_failed") return "failed";
244	  if (invoice.dueAt && new Date(invoice.dueAt).getTime() < Date.now() && !["paid", "paid_external", "voided"].includes(invoice.status)) return "overdue";
245	  return "upcoming";
246	}
247	
248	function ClientRow({ client, nextInvoice, onClick }: { client: any; nextInvoice: any; onClick: () => void }) {
249	  const fullName = `${client.firstName ?? ""} ${client.lastName ?? ""}`.trim() || "Client";
250	  const status = invoiceStatus(nextInvoice);
251	  const dueDate = nextInvoice?.dueAt ? new Date(nextInvoice.dueAt).toLocaleDateString("en-NZ", { day: "2-digit", month: "2-digit", year: "2-digit" }) : "-";
252	
253	  return (
254	    <div style={{ display: "grid", gridTemplateColumns: "1.7fr 1fr", gap: 12 }}>
255	      <div style={{ ...GLASS, borderRadius: 18, padding: "16px 16px 14px", position: "relative", display: "flex", flexDirection: "column", cursor: "pointer" }} onClick={onClick}>
256	        <button
257	          onClick={(event) => { event.stopPropagation(); onClick(); }}
258	          aria-label={`Open ${fullName}`}
259	          style={{ position: "absolute", top: 12, right: 12, width: 28, height: 28, borderRadius: 999, background: C.white, border: "none", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", boxShadow: "0 1px 3px rgba(4,13,109,0.12)" }}
260	        >
261	          <Pencil size={14} color={C.ink} strokeWidth={1.9} />
262	        </button>
263	        <div style={{ fontWeight: 600, fontSize: 14, color: C.ink, textTransform: "uppercase", letterSpacing: 0, paddingRight: 30, lineHeight: 1.25 }}>{fullName}</div>
264	        <div style={{ fontWeight: 500, fontSize: 12.5, color: C.ink, textTransform: "uppercase", letterSpacing: 0, marginTop: 5, lineHeight: 1.35 }}>{client.siteAddress || "site address needed"}</div>
265	        <div style={{ marginTop: 12 }}><StatusBox status={status} /></div>
266	      </div>
267	
268	      <div style={{ ...GLASS, borderRadius: 18, padding: "16px 12px", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center" }}>
269	        <div style={{ fontWeight: 900, fontSize: 27, color: C.ink, letterSpacing: 0, lineHeight: 1, fontVariantNumeric: "tabular-nums" }}>
270	          {nextInvoice ? fmtCents(nextInvoice.amountCents ?? 0) : "-"}
271	        </div>
272	        <div style={{ fontWeight: 500, fontSize: 11, color: C.mute, marginTop: 8 }}>next invoice</div>
273	        <div style={{ fontWeight: 600, fontSize: 11, color: C.mute, marginTop: 1, fontVariantNumeric: "tabular-nums" }}>{dueDate}</div>
274	      </div>
275	    </div>
276	  );
277	}
278	
279	export default function ClientDirectory() {
280	  const [, setLocation] = useLocation();
281	  const [search, setSearch] = useState("");
282	  const [showAdd, setShowAdd] = useState(false);
283	  const [showArchived, setShowArchived] = useState(false);
284	  const [saveError, setSaveError] = useState<string | null>(null);
285	  const queryClient = useQueryClient();
286	
287	  const { data: clients = [], isLoading } = useQuery<any[]>({
288	    queryKey: ["/api/trades/clients"],
289	    queryFn: () => tradesFetch("/api/trades/clients").then((response) => response.ok ? response.json() : []),
290	    staleTime: 60000,
291	    retry: false,
292	  });
293	
294	  const { data: invoices = [] } = useQuery<any[]>({
295	    queryKey: ["/api/trades/invoices"],
296	    queryFn: () => tradesFetch("/api/trades/invoices").then((response) => response.ok ? response.json() : []),
297	    staleTime: 30000,
298	    retry: false,
299	  });
300	
301	  const { data: archivedClients = [] } = useQuery<any[]>({
302	    queryKey: ["/api/trades/clients", "archived"],
303	    queryFn: () => tradesFetch("/api/trades/clients?includeArchived=true").then((response) => response.ok ? response.json() : []),
304	    select: (list: any[]) => list.filter((client: any) => client.status === "archived"),
305	    enabled: showArchived,
306	    staleTime: 30000,
307	    retry: false,
308	  });
309	
310	  const createMutation = useMutation({
311	    mutationFn: async (data: ClientForm) => {
312	      const response = await fetch("/api/trades/clients", {
313	        method: "POST",
314	        headers: { "Content-Type": "application/json", ...tradesHeaders() },
315	        body: JSON.stringify(data),
316	      });
317	      if (!response.ok) {
318	        const message = await response.json().then((body) => body.message).catch(() => `Error ${response.status}`);
319	        throw new Error(message);
320	      }
321	      return response.json();
322	    },
323	    onSuccess: () => {
324	      queryClient.invalidateQueries({ queryKey: ["/api/trades/clients"] });
325	      setSaveError(null);
326	      setShowAdd(false);
327	    },
328	    onError: (error) => {
329	      setSaveError(error instanceof Error ? error.message : "Failed to add client. The backend may not be connected yet.");
330	    },
331	  });
332	
333	  const restoreMutation = useMutation({
334	    mutationFn: async (id: string) => {
335	      const response = await fetch(`/api/trades/clients/${id}/unarchive`, { method: "POST", headers: tradesHeaders() });
336	      if (!response.ok) throw new Error("Failed to restore");
337	      return response.json();
338	    },
339	    onSuccess: () => {
340	      queryClient.invalidateQueries({ queryKey: ["/api/trades/clients"] });
341	    },
342	  });
343	
344	  const activeClients = clients.filter((client: any) => client.status !== "archived");
345	  const term = search.trim().toLowerCase();
346	  const filtered = activeClients.filter((client: any) => {
347	    const haystack = `${client.firstName ?? ""} ${client.lastName ?? ""} ${client.siteAddress ?? ""}`.toLowerCase();
348	    return !term || haystack.includes(term);
349	  });
350	
351	  const invoiceByClient = (clientId: string) => {
352	    const live = invoices
353	      .filter((invoice: any) => invoice.clientProfileId === clientId && invoice.status !== "voided")
354	      .sort((a: any, b: any) => new Date(b.createdAt ?? b.dueAt).getTime() - new Date(a.createdAt ?? a.dueAt).getTime());
355	    if (live.length === 0) return undefined;
356	
357	    const failed = live.find((invoice: any) => invoice.status === "dispatch_failed");
358	    if (failed) return failed;
359	    const overdue = live.find((invoice: any) => invoice.status === "overdue" || (invoice.dueAt && new Date(invoice.dueAt).getTime() < Date.now() && !["paid", "paid_external"].includes(invoice.status)));
360	    if (overdue) return overdue;
361	    const active = live.find((invoice: any) => LIVE_STATUSES.includes(invoice.status));
362	    if (active) return active;
363	    return live[0];
364	  };
365	
366	  return (
367	    <div style={{ background: C.white, minHeight: "100svh", display: "flex", justifyContent: "center" }}>
368	      <div style={{ width: "100%", maxWidth: 430, minHeight: "100svh", background: C.cream, paddingBottom: 130, fontFamily: "'Outfit', system-ui, sans-serif" }}>
369	        <div style={{ height: 54 }} />
370	
371	        <div style={{ padding: "0 18px" }}>
372	          <div style={{ background: C.ink, borderRadius: 24, padding: "26px 26px 30px", position: "relative" }}>
373	            <div style={{ fontWeight: 800, fontSize: 64, color: C.cream, letterSpacing: 0, lineHeight: 0.92, fontVariantNumeric: "tabular-nums" }}>
374	              {activeClients.length}
375	            </div>
376	            <div style={{ fontWeight: 600, fontSize: 12, color: C.cream, letterSpacing: 0, textTransform: "uppercase", marginTop: 6 }}>
377	              active client{activeClients.length !== 1 ? "s" : ""}
378	            </div>
379	            <button
380	              onClick={() => setShowAdd(true)}
381	              aria-label="Add client"
382	              style={{ position: "absolute", right: 24, bottom: -20, width: 46, height: 46, borderRadius: 999, background: C.cream, color: C.ink, border: "none", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", boxShadow: "0 6px 16px rgba(4,13,109,0.32)" }}
383	            >
384	              <Plus size={22} strokeWidth={2.6} />
385	            </button>
386	          </div>
387	        </div>
388	
389	        <div style={{ padding: "38px 18px 0", display: "flex", gap: 10 }}>
390	          <div style={{ flex: 1, display: "flex", alignItems: "center", gap: 10, background: C.gray, borderRadius: 14, padding: "0 14px", height: 46 }}>
391	            <Search size={18} color={C.ink} strokeWidth={2} />
392	            <input
393	              value={search}
394	              onChange={(event) => setSearch(event.target.value)}
395	              placeholder="search clients or site"
396	              style={{ flex: 1, minWidth: 0, border: "none", outline: "none", background: "transparent", fontFamily: "inherit", fontWeight: 500, fontSize: 14, color: C.ink }}
397	            />
398	            {search && (
399	              <button onClick={() => setSearch("")} aria-label="Clear search" style={{ border: "none", background: "transparent", cursor: "pointer", display: "flex", padding: 0 }}>
400	                <X size={16} color={C.mute} strokeWidth={2.2} />
401	              </button>
402	            )}
403	          </div>
404	          <button
405	            onClick={() => setLocation("/trades")}
406	            aria-label="Go to trades dashboard"
407	            style={{ width: 46, height: 46, borderRadius: 14, background: C.ink, color: C.cream, border: "none", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, cursor: "pointer" }}
408	          >
409	            <LayoutGrid size={20} fill={C.cream} strokeWidth={0} />
410	          </button>
411	        </div>
412	
413	        <div style={{ display: "flex", flexDirection: "column", gap: 14, padding: "16px 18px 0" }}>
414	          {isLoading ? (
415	            <div style={{ textAlign: "center", padding: "48px 0", color: C.mute, fontSize: 13 }}>loading clients...</div>
416	          ) : filtered.length === 0 ? (
417	            <div style={{ textAlign: "center", padding: "48px 0", color: C.mute, fontSize: 13 }}>
418	              {search ? `no clients match "${search}"` : "no clients yet - tap + to add your first"}
419	            </div>
420	          ) : (
421	            filtered.map((client: any) => (
422	              <ClientRow
423	                key={client.id}
424	                client={client}
425	                nextInvoice={invoiceByClient(client.id)}
426	                onClick={() => setLocation(`/trades/clients/${client.id}`)}
427	              />
428	            ))
429	          )}
430	        </div>
431	
432	        <div style={{ padding: "22px 18px 0" }}>
433	          <button
434	            onClick={() => setShowArchived((current) => !current)}
435	            style={{ background: "none", border: "none", color: C.mute, fontSize: 12, fontWeight: 700, cursor: "pointer", textTransform: "uppercase", letterSpacing: 0, padding: 0 }}
436	          >
437	            {showArchived ? "hide archived" : "show archived"}
438	          </button>
439	          {showArchived && (
440	            archivedClients.length === 0 ? (
441	              <div style={{ padding: "14px 0", color: C.mute, fontSize: 13 }}>no archived clients</div>
442	            ) : (
443	              <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 12 }}>
444	                {archivedClients.map((client: any) => (
445	                  <div key={client.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", borderRadius: 16, background: "#EDEDED" }}>
446	                    <div style={{ flex: 1, minWidth: 0 }}>
447	                      <div style={{ fontWeight: 700, fontSize: 13.5, color: C.ink, textTransform: "capitalize", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{client.firstName} {client.lastName}</div>
448	                      <div style={{ fontSize: 11.5, color: C.mute, marginTop: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{client.siteAddress}</div>
449	                    </div>
450	                    <button
451	                      onClick={() => restoreMutation.mutate(client.id)}
452	                      disabled={restoreMutation.isPending}
453	                      style={{ flexShrink: 0, background: C.ink, color: C.cream, border: "none", borderRadius: 10, padding: "8px 12px", fontSize: 12, fontWeight: 700, cursor: restoreMutation.isPending ? "default" : "pointer", opacity: restoreMutation.isPending ? 0.6 : 1, display: "flex", alignItems: "center", gap: 6 }}
454	                    >
455	                      <RotateCcw size={13} />
456	                      restore
457	                    </button>
458	                  </div>
459	                ))}
460	              </div>
461	            )
462	          )}
463	        </div>
464	
465	        {showAdd && (
466	          <AddClientSheet
467	            onClose={() => { setShowAdd(false); setSaveError(null); }}
468	            onSave={(data) => { setSaveError(null); createMutation.mutate(data); }}
469	            saving={createMutation.isPending}
470	            saveError={saveError}
471	          />
472	        )}
473	      </div>
474	    </div>
475	  );
476	}
