// API-level E2E for trades quick invoice (no client) + promote flow.
import jwt from '/home/runner/workspace/node_modules/jsonwebtoken/index.js';

const JWT_SECRET = '6e49bbb919ec21744436c9962c399fd40612d75af731e5e52cc37f6313bb679c8edca4d38371e20ae71d75adced9ab26b392e475f8f98176d1ed71b059894bfa';
const BASE = 'http://localhost:5000';
const token = jwt.sign({ userId: 'e2e', email: 'e2e@test.local', merchantId: 22, role: 'merchant' }, JWT_SECRET, { expiresIn: '1h' });
const H = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` };

const due = new Date(Date.now() + 7 * 864e5).toISOString();
let pass = 0, fail = 0;
const ok = (cond, name, extra = '') => { cond ? pass++ : fail++; console.log(`${cond ? '✅' : '❌'} ${name}${extra ? ' — ' + extra : ''}`); };

// 1. Quick invoice with inline recipient
let r = await fetch(`${BASE}/api/trades/invoices`, { method: 'POST', headers: H, body: JSON.stringify({
  recipient: { name: 'Quick Test', email: 'qt-e2e@example.com', channel: 'email' },
  amountCents: 12345, deliveryChannel: 'email', dueAt: due, kind: 'full', jobDetails: 'e2e quick invoice',
}) });
const inv = await r.json();
ok(r.status === 201, `create quick invoice → 201 (got ${r.status})`, inv.message || '');
ok(!!inv.clientProfileId, 'response has clientProfileId', inv.clientProfileId);
const prospectId = inv.clientProfileId;

// 2. Prospect exists with status prospect, carries contact details
r = await fetch(`${BASE}/api/trades/clients`, { headers: H });
const clients = await r.json();
const prospect = clients.find((c) => c.id === prospectId);
ok(!!prospect && prospect.status === 'prospect', `prospect profile status=prospect (got ${prospect?.status})`);
ok(prospect?.firstName === 'Quick' && prospect?.lastName === 'Test', `name split Quick/Test (got ${prospect?.firstName}/${prospect?.lastName})`);
ok(prospect?.email === 'qt-e2e@example.com', 'prospect carries email');

// 3. Invoice row exists + dispatch attempted
r = await fetch(`${BASE}/api/trades/invoices`, { headers: H });
const invRows = await r.json();
const row = invRows.find((i) => i.id === inv.id);
ok(!!row && row.clientProfileId === prospectId, 'invoice row linked to prospect');
console.log(`   delivery: delivered=${inv.delivered} reason=${inv.deliveryReason ?? '-'} status=${row?.status}`);

// 4. Checkout resolve works for the quick invoice token
r = await fetch(`${BASE}/api/trades/invoices/token/${inv.token}`).catch(() => null);
console.log(`   public token endpooint status (informational): ${r?.status}`);

// 5. Promote → active
r = await fetch(`${BASE}/api/trades/clients/${prospectId}/promote`, { method: 'POST', headers: H });
const promoted = await r.json();
ok(r.status === 200 && promoted.status === 'active', `promote → 200 active (got ${r.status}/${promoted.status})`);

// 6. Promote again → 400
r = await fetch(`${BASE}/api/trades/clients/${prospectId}/promote`, { method: 'POST', headers: H });
ok(r.status === 400, `re-promote → 400 (got ${r.status})`);

// 7. Validation failures
r = await fetch(`${BASE}/api/trades/invoices`, { method: 'POST', headers: H, body: JSON.stringify({ amountCents: 100, deliveryChannel: 'email', dueAt: due, kind: 'full' }) });
ok(r.status === 400, `neither client nor recipient → 400 (got ${r.status})`);
r = await fetch(`${BASE}/api/trades/invoices`, { method: 'POST', headers: H, body: JSON.stringify({ recipient: { name: 'X', channel: 'sms' }, amountCents: 100, deliveryChannel: 'sms', dueAt: due, kind: 'full' }) });
ok(r.status === 400, `sms recipient w/o phone → 400 (got ${r.status})`);
r = await fetch(`${BASE}/api/trades/invoices`, { method: 'POST', headers: H, body: JSON.stringify({ clientProfileId: prospectId, recipient: { name: 'X', email: 'x@y.z', channel: 'email' }, amountCents: 100, deliveryChannel: 'email', dueAt: due, kind: 'full' }) });
ok(r.status === 400, `both client AND recipient → 400 (got ${r.status})`);

// 8. Normal client-linked invoice still works (regression) — use promoted client
r = await fetch(`${BASE}/api/trades/invoices`, { method: 'POST', headers: H, body: JSON.stringify({ clientProfileId: prospectId, amountCents: 555, deliveryChannel: 'email', dueAt: due, kind: 'full' }) });
const reg = await r.json();
ok(r.status === 201, `client-linked invoice still works → 201 (got ${r.status})`, reg.message || '');

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

