// Browser E2E: dashboard tile → quick invoice flow → add client → directory redesign.
import { chromium } from '/home/runner/workspace/node_modules/playwright-core/index.mjs';
import jwt from '/home/runner/workspace/node_modules/jsonwebtoken/index.js';

const JWT_SECRET = '6e49bbb919ec21744436c9962c399fd40612d75af731e5e52cc37f6313bb679c8edca4d38371e20ae71d75adced9ab26b392e475f8f98176d1ed71b059894bfa';
const token = jwt.sign({ userId: 'e2e', email: 'e2e@test.local', merchantId: 22, role: 'merchant' }, JWT_SECRET, { expiresIn: '1h' });
const SHOT = (n) => `/tmp/claude-1000/-home-runner-workspace/0d6e3462-7c3a-41a8-a060-86c8d6ce5ea5/scratchpad/shot-${n}.png`;

const browser = await chromium.launch({ executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium', args: ['--no-sandbox', '--disable-dev-shm-usage'] });
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
await ctx.addInitScript((t) => { localStorage.setItem('authToken', t); }, token);
const page = await ctx.newPage();
page.on('pageerror', (e) => console.log('[pageerror]', String(e).slice(0, 200)));

const step = async (name, fn) => { try { await fn(); console.log('✅', name); } catch (e) { console.log('❌', name, '—', String(e).slice(0, 200)); } };

// 1. Dashboard → quick invoice tile
await page.goto('http://localhost:5000/trades', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(2500);
await step('dashboard renders with quick invoice tile', async () => {
  await page.waitForSelector('button[aria-label="quick invoice"]', { timeout, timeout: 10000 });
});
await page.click('button[aria-label="quick invoice"]');
await page.waitForTimeout(1400);

// 2. Keypad appears directly (quick mode)
await step('lands on amount keypad (no client picker)', async () => {
  await page.waitForSelector('.tp-kp', { timeout: 8000 });
});
for (const d of ['5', '0', '0', '0']) await page.click(`.tp-kp:has-text("${d}")`);
await page.screenshot({ path: SHOT('1-keypad') });
await page.click('button[aria-label="confirm"]');
await page.waitForTimeout(900);

// 3. Details screen with inline recipient fields
await step('quick invoice details screen shows recipient fields', async () => {
  await page.waitForSelector('input[placeholder="customer name"]', { timeout: 8000 });
});
await page.fill('input[placeholder="customer name"]', 'Browser Tester');
await page.fill('input[placeholder="customer email"]', 'browser-e2e@example.com');
await page.fill('input[placeholder="what\'s this invoice for?"]', 'gutter clean');
await page.screenshot({ path: SHOT('2-details') });

// 4. Send
await page.click('button:has-text("send invoice")');
await step('success screen with add client button', async () => {
  await page.waitForSelector('button:has-text("add client")', { timeout: 15000 });
});
await page.screenshot({ path: SHOT('3-success') });

// 5. Add client
await page.click('button:has-text("add client")');
await step('client saved state', async () => {
  await page.waitForSelector('button:has-text("client saved")', { timeout: 8000 });
});
await page.screenshot({ path: SHOT('4-saved') });

// 6. Directory redesign + new client present
await page.goto('http://localhost:5000/trades/clients', { waitUntil: 'load' });
await page.waitForTimeout(2200);
await step('redesigned directory shows hero + new client', async () => {
  await page.waitForSelector('.cdir-hero-count', { timeout: 8000 });
  await page.waitForSelector('.cdir-row:has-text("browser tester")', { timeout: 8000 });
});
await page.screenshot({ path: SHOT('5-directory'), fullPage: false });

// 7. Regression: terminal via subbar still offers client flow + quick entry
await page.goto('http://localhost:5000/trades/terminal', { waitUntil: 'load' });
await page.waitForTimeout(1800);
await page.click('button[aria-label="invoice"]');
await page.waitForTimeout(900);
await step('client picker shows quick-invoice shortcut', async () => {
  await page.waitForSelector('button:has-text("no client — just enter their details")', { timeout: 8000 });
});
await page.screenshot({ path: SHOT('6-picker') });

await browser.close();
console.log('done');

